from typing import Callable

from apps.cmc.adapter import CMCAdapter, CMCCall

DEFAULT_TOOL_PERMISSIONS = {
    "get_market_listings": True,
    "get_quotes": True,
    "get_global_metrics": True,
    "get_fear_and_greed": True,
    "news": False,
    "on_chain": False,
}

